css:
[aria-label="Liquid Glass ASCII background controls"],.liquid-glass-hud-pill,[data-liquid-glass-hud]{display:none!important}
[data-slot="sidebar-wrapper"]{position:relative;isolation:isolate;background:transparent!important}
[data-liquid-glass-ascii-backdrop]{background:radial-gradient(120% 90% at 50% 0%,#140a24 0%,#0b0614 55%,#07040d 100%)}
[data-liquid-glass-ascii-backdrop] canvas{opacity:.55!important}
[data-liquid-glass-ascii-backdrop] canvas.opacity-90{filter:hue-rotate(70deg)}
.liquid-glass-ambient-glow,[data-liquid-glass-aurora]{position:absolute;inset:-25%!important;pointer-events:none;will-change:transform;background:radial-gradient(closest-side at 24% 22%,rgb(168 85 247/38%),transparent),radial-gradient(closest-side at 70% 30%,rgb(124 58 237/30%),transparent),radial-gradient(closest-side at 58% 72%,rgb(192 38 211/26%),transparent),radial-gradient(closest-side at 18% 78%,rgb(79 70 229/24%),transparent),radial-gradient(closest-side at 86% 82%,rgb(45 212 191/8%),transparent);animation:lg-aurora 42s ease-in-out infinite alternate}
@keyframes lg-aurora{0%{transform:translate3d(-5%,-4%,0) rotate(0deg) scale(1)}50%{transform:translate3d(5%,3%,0) rotate(12deg) scale(1.1)}100%{transform:translate3d(-3%,5%,0) rotate(-8deg) scale(1.04)}}
@media (prefers-reduced-motion:reduce){.liquid-glass-ambient-glow,[data-liquid-glass-aurora]{animation:none}}
.liquid-glass-specular-sheen,[data-liquid-glass-sheen]{position:absolute;inset:0;pointer-events:none;mix-blend-mode:normal!important;background:radial-gradient(70% 50% at 50% 0%,rgb(216 180 254/7%),transparent 70%)!important}
[data-app-sidebar] [data-slot="sidebar-inner"],[data-slot="sidebar-inset"],[data-chat-header],[data-slot="card"],.chat-composer-shell{backdrop-filter:none!important;-webkit-backdrop-filter:none!important}
[data-slot="sidebar-inset"],div:has(>[data-chat-column-maximized-away]),[data-chat-header],[data-workspace-area="conversation"],.messages-timeline-scroll{background:transparent!important;box-shadow:none!important}
[data-app-sidebar] [data-slot="sidebar-inner"]{background:linear-gradient(180deg,rgb(168 85 247/7%),rgb(12 7 22/0%) 40%),rgb(14 8 26/55%)!important;border-inline-end:1px solid rgb(168 85 247/16%)!important;box-shadow:inset -1px 0 0 rgb(255 255 255/3%)!important}
[data-chat-header]{border-bottom:1px solid rgb(168 85 247/12%)!important}
[data-thread-item]{border-radius:12px!important}
[data-thread-item][data-active="true"],[data-thread-item][aria-current="page"],[data-thread-item][data-selected="true"]{background:linear-gradient(135deg,rgb(168 85 247/22%),rgb(124 58 237/10%))!important;box-shadow:inset 0 0 0 1px rgb(192 132 252/28%),0 0 18px -8px rgb(168 85 247/60%)!important}
[data-slot="composer-host"]{border-radius:18px!important;backdrop-filter:blur(16px) saturate(1.4)!important;-webkit-backdrop-filter:blur(16px) saturate(1.4)!important;background:linear-gradient(180deg,rgb(168 85 247/8%),rgb(168 85 247/2%)),rgb(18 10 32/62%)!important;border:1px solid rgb(168 85 247/22%)!important;box-shadow:0 20px 44px -20px rgb(0 0 0/70%),inset 0 1px 0 rgb(255 255 255/8%)!important}
[data-slot="composer-host"]:focus-within{border-color:rgb(192 132 252/45%)!important;box-shadow:0 20px 44px -20px rgb(0 0 0/70%),0 0 28px -8px rgb(168 85 247/55%),inset 0 1px 0 rgb(255 255 255/10%)!important}
[data-user-message-bubble]{border-radius:16px!important;background:linear-gradient(135deg,rgb(168 85 247/20%),rgb(124 58 237/10%)),rgb(18 10 32/60%)!important;border:1px solid rgb(192 132 252/24%)!important}
.chat-markdown-codeblock{border-radius:12px!important;background:rgb(10 6 20/72%)!important;border:1px solid rgb(168 85 247/14%)!important}
[data-slot="card"],[data-thread-details-card]{border-radius:16px!important;background:linear-gradient(180deg,rgb(168 85 247/6%),transparent 60%),rgb(18 10 32/70%)!important;border:1px solid rgb(168 85 247/18%)!important;box-shadow:inset 0 1px 0 rgb(255 255 255/5%)!important}
[data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"]{border-radius:16px!important;backdrop-filter:blur(18px) saturate(1.4);-webkit-backdrop-filter:blur(18px) saturate(1.4);background:rgb(20 11 36/86%)!important;border:1px solid rgb(168 85 247/22%)!important;box-shadow:0 28px 64px -20px rgb(0 0 0/75%),0 0 32px -16px rgb(168 85 247/45%),inset 0 1px 0 rgb(255 255 255/7%)!important}
[data-slot="tooltip-popup"]{background:rgb(24 13 42/94%)!important;border:1px solid rgb(168 85 247/25%)!important}
[data-slot="input"],[data-slot="select-trigger"]{background:rgb(12 7 22/55%)!important;border-color:rgb(168 85 247/18%)!important}
[data-slot="switch"][data-checked]{box-shadow:0 0 12px -2px rgb(168 85 247/60%)}
::-webkit-scrollbar-thumb{background-color:rgb(168 85 247/22%);border-radius:999px}
::-webkit-scrollbar-thumb:hover{background-color:rgb(168 85 247/38%)}
:root:not(.dark) [data-liquid-glass-ascii-backdrop]{background:radial-gradient(120% 90% at 50% 0%,#faf6ff 0%,#f1eaf9 60%,#e9e0f5 100%)}
:root:not(.dark) :is(.liquid-glass-ambient-glow,[data-liquid-glass-aurora]){opacity:.45}
:root:not(.dark) [data-app-sidebar] [data-slot="sidebar-inner"]{background:rgb(255 255 255/55%)!important;border-color:rgb(126 34 206/14%)!important}
:root:not(.dark) :is([data-slot="composer-host"],[data-user-message-bubble],[data-slot="card"],[data-thread-details-card],.chat-markdown-codeblock){background:rgb(255 255 255/72%)!important;border-color:rgb(126 34 206/18%)!important}
:root:not(.dark) :is([data-slot="dialog-popup"],[data-slot="popover-popup"],[data-slot="menu-popup"],[data-slot="tooltip-popup"]){background:rgb(255 255 255/92%)!important}

[data-preview-panel-mode]{background:rgb(14 8 26/55%)!important;border-inline-start:1px solid rgb(168 85 247/16%)!important;border-left-color:rgb(168 85 247/16%)!important;-webkit-backdrop-filter:none!important;backdrop-filter:none!important}
[data-right-panel-tabbar]{background:transparent!important;border-bottom:1px solid rgb(168 85 247/12%)!important}
[data-right-panel-surface-content]>.bg-background,[data-right-panel-surface-content]>[aria-label="Open a surface"]{background:transparent!important}
[aria-label="Open a surface"] .group>button{border-radius:10px!important}
[aria-label="Open a surface"] .group:hover>button,[aria-label="Open a surface"] .group>button.bg-accent\/60{background:rgb(168 85 247/14%)!important}
[aria-label="Open a surface"] [data-slot="kbd"]{background:rgb(168 85 247/14%)!important;border:1px solid rgb(168 85 247/22%)!important}
:root:not(.dark) [data-preview-panel-mode]{background:rgb(255 255 255/60%)!important;border-inline-start-color:rgb(126 34 206/14%)!important;border-left-color:rgb(126 34 206/14%)!important}
:root:not(.dark) [data-right-panel-tabbar]{border-bottom-color:rgb(126 34 206/14%)!important}
:root:not(.dark) [aria-label="Open a surface"] [data-slot="kbd"]{border-color:rgb(126 34 206/14%)!important}

[data-timeline-loading],[data-slot="sidebar-inset"]>.bg-background,[data-workspace-area="pull-requests"],[data-workspace-area="pull-requests"]>header{background:transparent!important}
[data-slot="dialog-popup"][data-app-modal]{backdrop-filter:none!important;-webkit-backdrop-filter:none!important;background:linear-gradient(180deg,rgb(168 85 247/6%),transparent 50%),rgb(14 8 26/80%)!important}
[data-slot="command-dialog-popup"]{border-radius:16px!important;background:rgb(20 11 36/88%)!important;border:1px solid rgb(168 85 247/22%)!important;box-shadow:0 28px 64px -20px rgb(0 0 0/75%),0 0 32px -16px rgb(168 85 247/45%)!important}
[data-workspace-area="settings-nav"]{background:rgb(14 8 26/40%)!important;border-inline-end-color:rgb(168 85 247/16%)!important}
[data-slot="settings-group"].rounded-xl{border-radius:16px!important;background:linear-gradient(180deg,rgb(168 85 247/6%),transparent 60%),rgb(18 10 32/70%)!important;border:1px solid rgb(168 85 247/18%)!important}
:root:not(.dark) [data-slot="dialog-popup"][data-app-modal]{background:rgb(255 255 255/72%)!important;border-color:rgb(126 34 206/14%)!important}
:root:not(.dark) [data-slot="command-dialog-popup"]{background:rgb(255 255 255/92%)!important;border-color:rgb(126 34 206/14%)!important}
:root:not(.dark) [data-workspace-area="settings-nav"]{background:rgb(255 255 255/50%)!important;border-inline-end-color:rgb(126 34 206/14%)!important}
:root:not(.dark) [data-slot="settings-group"].rounded-xl{background:rgb(255 255 255/60%)!important;border-color:rgb(126 34 206/14%)!important}
